<?php require_once "../config/auth.php";require_login();$err="";$ok="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$a=(float)$_POST["amount"];$m=trim($_POST["method"]);$tx=trim($_POST["txid"]);if($a<20||strlen($tx)<4)$err="Minimum deposit is ৳20.";else{$q=db()->prepare("INSERT INTO deposits(user_id,amount,method,transaction_id) VALUES(?,?,?,?)");$q->execute([$_SESSION["user_id"],$a,$m,$tx]);$ok="Deposit submitted for admin approval.";}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><main><form class="box" method="post"><h1>Add Funds</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if($ok):?><div class="success"><?=$ok?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="amount" type="number" min="20" placeholder="Amount (minimum ৳20)" required><select name="method"><option>bKash</option><option>Nagad</option><option>Manual</option></select><input name="txid" placeholder="Transaction ID" required><button>Submit Deposit</button></form></main></body></html>